namespace SCTools.GameData;

/// <summary>
/// What a station or a city has, as UEX (uexcorp.space) lists it: its services the way the game's starmap names them (Refinery, Cargo deck, Clinic ...) and
/// its shops by name (the item shops, the ship dealers and rentals). System: the star system's id of the map; Nickname: UEX's short name ("Grim HEX" for
/// Green Imperial Housing Exchange), where it has one.
/// </summary>
public sealed record StationInfo(string System, string Name, string? Nickname, string[] Services, string[] Shops);

