    static readonly Lazy<Dictionary<string, StationInfo>> _byKey = new(() =>
    {
        var d = new Dictionary<string, StationInfo>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in StarMap.Places)
            if (!p.Hidden && p.Kind is PlaceKind.Station or PlaceKind.City or PlaceKind.Gateway && Of(p) is { } info) d[p.Key] = info;
        return d;
    });

    /// <summary>The entries by the key of the place of the map they are ("pyro/ruin-station").</summary>
    public static IReadOnlyDictionary<string, StationInfo> ByKey => _byKey.Value;

    /// <summary>UEX's entry for a place of the map, by its name in its system (null: UEX has none, or the place is not a station, a city or a gateway).</summary>
    public static StationInfo? Of(Place place)
    {
        var want = Plain(place.Name);
        foreach (var info in All)
            if (info.System == place.System && (Plain(info.Name) == want || (info.Nickname != null && Plain(info.Nickname) == want))) return info;
        return null;
    }

    /// <summary>A name as letters and digits alone, without a system in brackets and without "station" at the end: the names of the two sources differ in those.</summary>
    static string Plain(string name)
    {
        var cut = name.IndexOf('(');
        var s = StarMap.Letters(cut > 0 ? name[..cut] : name);
        return s.EndsWith("station", StringComparison.Ordinal) && s.Length > 7 ? s[..^7] : s;
    }
}
